const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
const between = (min, max) => Math.floor(min + Math.random() * (max - min + 1));
class Evented { constructor(){ this.listeners = new Map(); } on(e, cb){ const list=this.listeners.get(e)||[]; list.push({cb, once:false}); this.listeners.set(e,list); return this; } once(e, cb){ const list=this.listeners.get(e)||[]; list.push({cb, once:true}); this.listeners.set(e,list); return this; } emit(e,...args){ const list=[...(this.listeners.get(e)||[])]; this.listeners.set(e, list.filter(l=>!l.once)); for(const l of list) l.cb(...args); } }
function color(n){return `#${(n>>>0).toString(16).padStart(6,"0").slice(-6)}`}
class GameObject extends Evented { constructor(scene,x=0,y=0){ super(); this.scene=scene; this.x=x; this.y=y; this.alpha=1; this.visible=true; this.scale=1; this.scaleX=1; this.scaleY=1; this.rotation=0; this.depth=0; this.active=true; this.data={}; this.width=0; this.height=0; } setOrigin(x=0.5,y=x){this.originX=x;this.originY=y;return this} setStrokeStyle(w,c,a=1){this.strokeWidth=w;this.strokeColor=c;this.strokeAlpha=a;return this} setFillStyle(c,a=1){this.fillColor=c;this.fillAlpha=a;return this} setInteractive(){return this} setDepth(v){this.depth=v;return this} setScale(x=1,y=x){this.scale=x;this.scaleX=x;this.scaleY=y;return this} setRotation(v){this.rotation=v;return this} setTint(v){this.tint=v;return this} setAlpha(v){this.alpha=v;return this} setSize(w,h){this.width=w;this.height=h;return this} setData(k,v){this.data[k]=v;return this} getData(k){return this.data[k]} destroy(){this.active=false; if(this.scene) this.scene._remove(this)} updateTransform(){} }
class Container extends GameObject { constructor(scene,x=0,y=0){ super(scene,x,y); this.children=[]; } add(children){ if(Array.isArray(children)) this.children.push(...children); else this.children.push(children); return this; } }
class Rectangle extends GameObject { constructor(scene,x,y,w,h,r=0,c=0xffffff,a=1){ super(scene,x,y); this.width=w; this.height=h; this.radius=r; this.fillColor=c; this.fillAlpha=a; } }
class Circle extends GameObject { constructor(scene,x,y,r,c=0xffffff,a=1){ super(scene,x,y); this.radius=r; this.width=r*2; this.height=r*2; this.fillColor=c; this.fillAlpha=a; } }
class Image extends GameObject { constructor(scene,x,y,key){ super(scene,x,y); this.key=key; this.width=64; this.height=64; } }
class Text extends GameObject { constructor(scene,x,y,text,style={}){ super(scene,x,y); this.text=String(text); this.style=style; this.width=this.text.length*12; this.height=24; } setText(t){this.text=String(t); return this} }
class TileSprite extends Rectangle { constructor(scene,x,y,w,h,key){ super(scene,x,y,w,h,0,0xffffff,1); this.key=key; this.tilePositionX=0; this.tilePositionY=0; } }
class Zone extends Rectangle { constructor(scene,x,y,w,h){ super(scene,x,y,w,h,0,0,0); } }
class Graphics extends GameObject { constructor(scene){ super(scene,0,0); } fillStyle(){return this} fillRect(){return this} fillCircle(){return this} fillEllipse(){return this} fillTriangle(){return this} lineStyle(){return this} strokeEllipse(){return this} strokeCircle(){return this} strokeLineShape(){return this} generateTexture(key,w,h){this.scene.textures.add(key,{w,h})} }
class ParticleEmitter extends GameObject { explode(){} setPosition(x,y){this.x=x;this.y=y;return this} }
class Body { constructor(gameObject){this.gameObject=gameObject; this.isStatic=false; this.radius=0;} setCircle(r){this.radius=r;return this} setAllowGravity(){return this} setImmovable(){return this} updateFromGameObject(){} }
class StaticBody extends Body { constructor(go){super(go); this.isStatic=true;} }
class Group { constructor(){this.children=[];} add(o){ if(!this.children.includes(o)) this.children.push(o); } remove(o,destroy=false){ this.children=this.children.filter(c=>c!==o); if(destroy&&o.destroy)o.destroy(); } getChildren(){return this.children;} }
class ScenePlugin { constructor(scene){this.scene=scene; this.game=null;} start(key,data){this.game?.start(key,data)} launch(key,data){this.game?.launch(key,data)} stop(key){this.game?.stop(key||this.scene.sceneKey)} pause(key){this.game?.pause(key||this.scene.sceneKey)} resume(key){this.game?.resume(key)} isPaused(key){return this.game?.paused.has(key||this.scene.sceneKey)||false} }
class Scene { constructor(key){this.sceneKey=typeof key==='string'?key:key?.key; this.children=[]; this.paused=false;} _install(game){this.game=game; this.scale=game.scale; this.scene=new ScenePlugin(this); this.scene.game=game; this.textures=game.textures; this.add=game.addFactory(this); this.make=game.makeFactory(this); this.physics=game.physicsFactory(this); this.tweens=game.tweens; this.time=game.time; this.cameras=game.cameras; this.input=game.input; } _add(o){this.children.push(o);return o} _remove(o){this.children=this.children.filter(c=>c!==o)} }
class Game { constructor(config){this.config=config; this.scale={width:config.scale?.width||960,height:config.scale?.height||540}; this.textures={map:new Map(), exists:k=>this.textures.map.has(k), add:(k,v)=>this.textures.map.set(k,v)}; this.paused=new Set(); this.scenes=new Map(); this.tweens={add: cfg=>{ if(cfg?.onComplete) setTimeout(cfg.onComplete, cfg.duration||0); return cfg; }}; this.time={delayedCall:(delay,cb)=>setTimeout(cb,delay)}; this.cameras={main:{shake(){},flash(){}}}; this.input=new Evented(); this.input.keyboard=new Evented(); this._setupRenderer(config.parent); for(const S of config.scene||[]){const s=new S(); s._install(this); this.scenes.set(s.sceneKey,s);} requestAnimationFrame(()=>this.start(config.scene?.[0] ? new config.scene[0]().sceneKey : [...this.scenes.keys()][0])); }
_setupRenderer(parent){ const host=document.getElementById(parent)||document.body; const canvas=document.createElement('canvas'); canvas.width=this.scale.width; canvas.height=this.scale.height; canvas.style.width='100%'; canvas.style.height='100%'; host.appendChild(canvas); this.canvas=canvas; const unlock=e=>this.input.emit('pointerdown',{x:e.clientX||0,y:e.clientY||0,isDown:true}); canvas.addEventListener('pointerdown',unlock); window.addEventListener('keydown',e=>this.input.keyboard.emit('keydown-'+e.key.toUpperCase())); }
addFactory(scene){ return { existing:o=>scene._add(o), rectangle:(...a)=>scene._add(new Rectangle(scene,...a)), circle:(...a)=>scene._add(new Circle(scene,...a)), image:(...a)=>scene._add(new Image(scene,...a)), text:(...a)=>scene._add(new Text(scene,...a)), tileSprite:(...a)=>scene._add(new TileSprite(scene,...a)), zone:(...a)=>scene._add(new Zone(scene,...a)), particles:(...a)=>scene._add(new ParticleEmitter(scene,...a)) }; }
makeFactory(scene){ return { graphics:()=>new Graphics(scene) }; }
physicsFactory(scene){ return { add: { existing:(o,isStatic=false)=>{o.body=isStatic?new StaticBody(o):new Body(o);}, group:()=>new Group(), overlap:(a,g,cb)=>{scene._overlap={a,g,cb};} } }; }
start(key,data){ const s=this.scenes.get(key); if(!s) return; this.current=s; this.paused.delete(key); if(s.init) s.init(data||{}); if(s.create) s.create(data||{}); this.loop(); }
launch(key,data){ const s=this.scenes.get(key); if(!s) return; if(s.init) s.init(data||{}); if(s.create) s.create(data||{}); }
stop(key){this.paused.add(key)} pause(key){this.paused.add(key)} resume(key){this.paused.delete(key)} loop(){ let last=performance.now(); const tick=now=>{ if(this.current && !this.paused.has(this.current.sceneKey) && this.current.update) this.current.update(now, now-last); last=now; requestAnimationFrame(tick);}; requestAnimationFrame(tick); } }
const Phaser={AUTO:0, Scale:{FIT:'FIT',CENTER_BOTH:'CENTER_BOTH'}, Math:{Clamp:clamp,Between:between}, Geom:{Line:class{constructor(x1,y1,x2,y2){Object.assign(this,{x1,y1,x2,y2})}}}, Utils:{Array:{Remove:(arr,item)=>{const i=arr.indexOf(item); if(i>=0)return arr.splice(i,1)[0]; return null;}}}, Physics:{Arcade:{Body,StaticBody,Group}}, Input:{Pointer:class{}}, GameObjects:{GameObject,Container,Rectangle,Circle,Image,Text,TileSprite,Zone,Graphics,Particles:{ParticleEmitter}}, Scene, Game};
const renderObject=(ctx,o)=>{ if(!o.visible||!o.active)return; ctx.save(); ctx.globalAlpha=o.alpha??1; ctx.translate(o.x,o.y); ctx.rotate(o.rotation||0); ctx.scale(o.scaleX||o.scale||1,o.scaleY||o.scale||1); if(o instanceof Container){ for(const c of o.children) renderObject(ctx,c); } else if(o instanceof Text){ ctx.fillStyle=o.style?.color||'#fff'; ctx.font=`${o.style?.fontSize||'20px'} ${o.style?.fontFamily||'sans-serif'}`; ctx.textAlign='center'; ctx.textBaseline='middle'; if(o.style?.stroke){ctx.strokeStyle=o.style.stroke; ctx.lineWidth=o.style.strokeThickness||2; ctx.strokeText(o.text,0,0)} ctx.fillText(o.text,0,0); } else if(o instanceof Circle){ ctx.fillStyle=color(o.fillColor||0xffffff); ctx.beginPath(); ctx.arc(0,0,o.radius,0,Math.PI*2); ctx.fill(); } else if(o instanceof Rectangle){ ctx.fillStyle=color(o.fillColor||0x111111); ctx.fillRect(-o.width/2,-o.height/2,o.width,o.height); if(o.strokeWidth){ctx.strokeStyle=color(o.strokeColor||0xffffff);ctx.lineWidth=o.strokeWidth;ctx.strokeRect(-o.width/2,-o.height/2,o.width,o.height)} } else if(o instanceof Image){ ctx.fillStyle='#14f7ff'; ctx.beginPath(); ctx.ellipse(0,0,28,16,0,0,Math.PI*2); ctx.fill(); ctx.fillStyle='#ff2bd6'; ctx.beginPath(); ctx.moveTo(-24,0); ctx.lineTo(8,-17); ctx.lineTo(8,17); ctx.closePath(); ctx.fill(); } ctx.restore();};
Game.prototype._render=function(){ if(!this.ctx||!this.current)return; this.ctx.fillStyle='#050012'; this.ctx.fillRect(0,0,this.scale.width,this.scale.height); const list=[...this.current.children].sort((a,b)=>(a.depth||0)-(b.depth||0)); for(const o of list) renderObject(this.ctx,o); };
const oldSetup=Game.prototype._setupRenderer; Game.prototype._setupRenderer=function(parent){ oldSetup.call(this,parent); this.ctx=this.canvas.getContext('2d'); };
const oldLoop=Game.prototype.loop; Game.prototype.loop=function(){ let last=performance.now(); const tick=now=>{ if(this.current && !this.paused.has(this.current.sceneKey) && this.current.update) this.current.update(now, now-last); this._render(); last=now; requestAnimationFrame(tick);}; requestAnimationFrame(tick); };
export default Phaser;
export { Scene, Game };
